function fashion(){document.body.dataset.section='fashion';app.innerHTML=`<section class="fashion-page"><div class="fashion-heading"><button class="back" id="fashion-back">← Todos os jogos</button><span>SEU PEQUENO ATELIÊ</span><h1>Moda <i>&</i> Estilo</h1><p>Um mundo de cores. Um look do seu jeitinho.</p></div><div class="atelier"><section class="dressing-room"><div class="mirror-label">✧ Espelho, espelho meu ✧</div><div id="avatar-stage"></div><div class="zoom-controls"><button id="full-body">↔ Corpo inteiro</button><button id="zoom-face">♡ Ver o rosto</button></div><p class="mirror-tip">Toque no cabelo, nos olhos ou na boca para mudar.</p></section><section class="wardrobe"><div class="wardrobe-head"><div><small>MISTURE E COMBINE</small><h2>Meu guarda-roupa</h2></div><span>✿</span></div><div class="style-presets">${['Casual','Romântico','Esportivo','Festa','Colegial','Bailarina','Verão','Rock','Rumi · K-pop','Mira · K-pop','Zoey · K-pop','Boho','Marinheiro','Inverno','Princesa','Jessie · Toy Story','Betty · Toy Story'].map((n,i)=>`<button data-preset="${i}">${n}</button>`).join('')}</div><div class="category-tabs" role="group" aria-label="Categorias">${Object.keys(fashionOptions).map(k=>`<button data-category="${k}">${fashionLabels[k]}</button>`).join('')}</div><div id="piece-palette"></div><div id="fashion-options"></div><div class="look-actions"><button id="save-look">♡ Salvar meu look</button><button id="reset-look">Recomeçar</button></div><p class="save-note">Seu look fica guardado neste navegador.</p></section></div></section>`;
 $('#fashion-back').onclick=home;$('#full-body').onclick=()=>{faceZoom=false;drawFashion()};$('#zoom-face').onclick=()=>{faceZoom=true;fashionCategory='hair';drawFashion()};
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{fashionCategory=b.dataset.category;faceZoom=['hair','hairColor','eyes','lip','earrings','eyeExpression','mouthExpression','eyeStyle','mouthStyle'].includes(fashionCategory);drawFashion()});
 document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const n=+b.dataset.preset;for(const k of ['top','skirt','shoes'])look[k]=n;look.earrings=n%4;look.necklace=n<8?n%4:3;look.bag=n>=8?4:n%4;if(n>=8&&n<=10){look.hair=n-4;look.hairColor=[4,5,1][n-8];}if(n>=15){look.hair=n-8;look.hairColor=n===15?3:2;look.necklace=0;look.earrings=0;}faceZoom=false;drawFashion();chime()});
 $('#save-look').onclick=()=>{try{localStorage.setItem('alice-isabela-look',JSON.stringify(look));notify('Look salvo! Ele estará aqui quando você voltar.')}catch{notify('Não foi possível salvar neste navegador.')}};
 $('#reset-look').onclick=()=>{look={...fashionDefault,tints:{}};faceZoom=false;drawFashion()};drawFashion();window.scrollTo(0,0);
}
function drawFashion(){
 $('#avatar-stage').innerHTML=fashionScene(look.background)+avatar(look,true);$('#avatar-stage').classList.toggle('zoomed',faceZoom);
 document.querySelectorAll('[data-face]').forEach(b=>{const activate=()=>{faceZoom=true;fashionCategory=b.dataset.face;drawFashion()};b.onclick=activate;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}}});
 document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.category===fashionCategory));
 drawPiecePalette();
 const colors={skin:skinColors,hairColor:hairColors,eyes:eyeColors,lip:lipColors};
 $('#fashion-options').innerHTML=`<h3>${fashionLabels[fashionCategory]}</h3><div class="option-grid">${(fashionCategory==='skin'?[8,0,9,4,10,1,11,5,12,2,13,6,7,14,3,15]:fashionOptions[fashionCategory].map((_,i)=>i)).map(i=>{const name=fashionOptions[fashionCategory][i];let sample={...look,[fashionCategory]:i};if(fashionCategory==='eyeStyle')sample.eyeExpression=0;if(fashionCategory==='mouthStyle')sample.mouthExpression=0;let visual=colors[fashionCategory]?`<span class="color-sample" style="background:${colors[fashionCategory][i]}"></span>`:avatar(sample,false);if(['eyeExpression','mouthExpression','eyeStyle','mouthStyle'].includes(fashionCategory))visual=visual.replace('0 0 300 510',['eyeExpression','eyeStyle'].includes(fashionCategory)?'96 92 108 63':'115 132 72 47');if(fashionCategory==='hair')visual=visual.replace('0 0 300 510','45 8 215 300');if(fashionCategory==='background')visual=fashionScene(i);if(fashionCategory==='bag')visual=visual.replace('0 0 300 510','166 235 87 121');return `<button class="look-option preview-${fashionCategory}" data-option="${i}" aria-pressed="${look[fashionCategory]===i}">${visual}<span>${name}</span></button>`}).join('')}</div>`;
 document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{look[fashionCategory]=+b.dataset.option;drawFashion();chime()});
}
home=function(){document.body.dataset.section='home';faceZoom=false;app.innerHTML=`<section class="portal"><div class="portal-stars" aria-hidden="true">✧ · ♡ · ✧</div><p class="portal-kicker">UM CANTINHO FEITO PARA VOCÊS</p><h1>Jogos de<br><span class="alice">Alice</span> <span class="and">e</span> <span class="isabela">Isabela</span></h1><p class="portal-subtitle">Duas irmãs. Mil histórias para inventar.</p><div class="game-cards"><button class="game-card toys-card" id="toys-section"><div class="game-cover"><img class="room-cover" src="assets/andy.png" alt="Quarto dos brinquedos"><img class="cover-woody" src="assets/toys/imported/woody-inert-v1.png" alt="Woody"><img class="cover-buzz" src="assets/toys/imported/buzz-lightyear-inert-v1.png" alt="Buzz Lightyear"><span class="cover-badge">⌕ ENCONTRE SEUS AMIGOS</span></div><div class="game-card-copy"><small>UMA AVENTURA EM CADA CANTINHO</small><h2>Brinquedos <span>↗</span></h2><p>Explore os quartos e encontre os brinquedos escondidos.</p></div></button><button class="game-card fashion-card" id="fashion-section"><div class="game-cover fashion-cover"><span class="fashion-spark one">✧</span><span class="fashion-spark two">✿</span>${avatar(fashionDefault)}<span class="cover-badge">♡ CRIE SEU LOOK</span></div><div class="game-card-copy"><small>SEU MUNDO DE CORES E BELEZA</small><h2>Moda e Estilo <span>↗</span></h2><p>Roupas, cabelos e acessórios para soltar a imaginação.</p></div></button></div><p class="portal-bottom">Feito com carinho, para brincar sem pressa. ♡</p></section>`;$('#toys-section').onclick=()=>choose('search');$('#fashion-section').onclick=fashion;window.scrollTo(0,0)};
const toyChoose=choose;choose=function(){document.body.dataset.section='toys';toyChoose('search');const status=app.querySelector('.status');if(status)status.textContent='Escolha seu quarto favorito e encontre os cinco brinquedos da lista.'};
document.title='Jogos de Alice e Isabela';$('.brand').innerHTML='<span class="brand-star">✿</span><span>JOGOS DE<br><b><span class="alice">Alice</span> e <span class="isabela">Isabela</span></b></span>';
document.querySelector('footer').innerHTML='Um cantinho de imaginação para Alice e Isabela <span>♡</span> Feito para brincar juntas';
